/**
 * Jhanvika Jewelleries — animated diamond hero.
 * Single file. The jewellery pictures are EMBEDDED inside this file
 * (transparent cut-outs, no background) — no image files or links needed.
 *
 * All 6 ornaments stay in their own section of the diamond and each one
 * revolves 360° in its own place. The diamond, dividers and background never move.
 */
const SPIN_SECONDS = 5; // time for one full 360° turn (then it repeats)
const STAGGER = 0.3; // seconds between one ornament starting and the next
const BORDER_COLOR = "#a7aeb8"; // flat matte silver border + dividers (no glow, no shine)
// inside the diamond = cream background behind the ornaments (outside = maroon)
// whole section background = same deep maroon as inside the diamond
const OUTSIDE_BG = "radial-gradient(ellipse 70% 80% at 50% 45%, #6a1022 0%, #4a0612 55%, #3a0410 100%)";

/* ------------------------------------------------------------------ */
/* Frame geometry (viewBox 1536 x 1024, from the reference image)       */
/* ------------------------------------------------------------------ */
const VW = 1536;
const VH = 1024;
const OUTER = "410,118 1125,118 1320,320 760,945 205,320";
/* every divider starts and ends exactly on the outline or on another divider */
const DIVIDERS = [
  [560, 118, 680, 437], // top-left slant   : top edge -> middle line
  [995, 118, 845, 437], // top-right slant  : top edge -> middle line
  [309, 437, 1215, 437], // middle line      : left edge -> right edge
  [690, 437, 582, 745], // bottom-left slant: middle line -> lower-left edge
  [850, 437, 939, 745], // bottom-right slant: middle line -> lower-right edge
];
const CELLS = [
  [[205, 320], [410, 118], [560, 118], [680, 437], [309, 437]],
  [[560, 118], [995, 118], [845, 437], [680, 437]],
  [[995, 118], [1125, 118], [1320, 320], [1215, 437], [845, 437]],
  [[309, 437], [690, 437], [582, 745]],
  [[690, 437], [850, 437], [939, 745], [760, 945], [582, 745]],
  [[850, 437], [1215, 437], [939, 745]],
];

/* The six ornaments, embedded. x / y / w / h = where each sits (viewBox units) */
const ITEMS = [
  {
    id: "necklace",
    label: "Bridal necklace",
    x: 292,
    y: 177,
    w: 319,
    h: 245,
    src: "data:image/webp;base64,",
  },
  {
    id: "jhumka",
    label: "Jhumka earrings",
    x: 664,
    y: 167,
    w: 214,
    h: 214,
    src: "data:image/webp;base64,",
  },
  {
    id: "ring",
    label: "Diamond ring",
    x: 967,
    y: 222,
    w: 236,
    h: 155,
    src: "data:image/webp;base64,",
  },
  {
    id: "bangles",
    label: "Gold bangles",
    x: 418,
    y: 467,
    w: 217,
    h: 146,
    src: "data:image/webp;base64,",
  },
  {
    id: "mangalsutra",
    label: "Mangalsutra",
    x: 686,
    y: 477,
    w: 164,
    h: 320,
    src: "data:image/webp;base64,",
  },
  {
    id: "nosepin",
    label: "Nose ring",
    x: 930,
    y: 474,
    w: 146,
    h: 152,
    src: "data:image/webp;base64,",
  },
];

/* ------------------------------------------------------------------ */
/* Styles                                                               */
/* ------------------------------------------------------------------ */
const CSS = `
.jh-stage {
  position: relative;
  width: min(94vw, 760px, 118vh);
  aspect-ratio: 1536 / 1024;
  margin: 0 auto;
  z-index: 10;
}

/* Everything inside is clipped to the diamond silhouette */
.jh-clip {
  position: absolute;
  inset: 0;
  clip-path: polygon(26.69% 11.52%, 73.24% 11.52%, 85.94% 31.25%, 49.48% 92.29%, 13.35% 31.25%);
  -webkit-clip-path: polygon(26.69% 11.52%, 73.24% 11.52%, 85.94% 31.25%, 49.48% 92.29%, 13.35% 31.25%);
}

.jh-velvet {
  position: absolute;
  inset: 0;
  background: #faf5ea; /* inside the diamond = cream */
}

.jh-layer { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }

/* each section clips its ornament, so nothing can cross a divider or the outline */
.jh-cellbox { position: absolute; inset: 0; pointer-events: none; }

/* each ornament sits in its own place; the wrapper gives the 3D depth */
.jh-pos {
  position: absolute;
  perspective: 700px;
  opacity: 0;
  animation: jh-in 0.9s ease forwards;
  pointer-events: none;
}
@keyframes jh-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.jh-pos img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  user-select: none;
  transform-origin: 50% 50%;
  will-change: transform, filter;
  filter: drop-shadow(0 6px 8px rgba(0, 0, 0, 0.45));
  animation: jh-spin var(--spin, 5s) cubic-bezier(0.45, 0, 0.25, 1) infinite;
}

/*
  one cycle = one full 360 degree turn in place, a soft light glint while it
  turns, a short hold with a tiny float, then it starts again seamlessly
*/
@keyframes jh-spin {
  0%   { transform: rotateY(0deg) translateY(0);        filter: drop-shadow(0 6px 8px rgba(0,0,0,.45)) brightness(1); }
  25%  { transform: rotateY(130deg) translateY(-1%);    filter: drop-shadow(0 6px 8px rgba(0,0,0,.45)) brightness(0.8); }
  38%  { transform: rotateY(215deg) translateY(-1.5%);  filter: drop-shadow(0 6px 8px rgba(0,0,0,.45)) brightness(1.3); }
  60%  { transform: rotateY(360deg) translateY(0);      filter: drop-shadow(0 6px 8px rgba(0,0,0,.45)) brightness(1); }
  80%  { transform: rotateY(360deg) translateY(-1.5%);  filter: drop-shadow(0 6px 8px rgba(0,0,0,.45)) brightness(1.08); }
  100% { transform: rotateY(360deg) translateY(0);      filter: drop-shadow(0 6px 8px rgba(0,0,0,.45)) brightness(1); }
}

.jh-sheen {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse 35% 30% at 50% 45%, rgba(255, 255, 255, 0.35), transparent 70%);
  animation: jh-breathe 5s ease-in-out infinite;
}
@keyframes jh-breathe {
  0%, 100% { opacity: 0.55; }
  50% { opacity: 1; }
}

/* ---------- Frame (never moves) ---------- */
.jh-frame { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; overflow: visible; }

@media (max-width: 767px) {
  .jh-stage { width: 100vw; margin: 0 auto; }
}

@media (prefers-reduced-motion: reduce) {
  .jh-pos img { animation: none; }
  .jh-sheen { animation: none; }
}
`;

const polyPoints = (pts) => pts.map((p) => p.join(",")).join(" ");
const cellClip = (pts) =>
  `polygon(${pts.map(([x, y]) => `${((x / VW) * 100).toFixed(3)}% ${((y / VH) * 100).toFixed(3)}%`).join(", ")})`;

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */
export default function Hero() {
  return (
    <section
      className="relative overflow-hidden flex items-center justify-center py-3 md:py-4"
      style={{ background: OUTSIDE_BG }}
    >
      <style>{CSS}</style>

      <div className="jh-stage">
        <div className="jh-clip">
          <div className="jh-velvet" />

          {/* very soft cream tone for each of the 6 sections */}
          <svg className="jh-layer" viewBox={`0 0 ${VW} ${VH}`} preserveAspectRatio="none" aria-hidden="true">
            <defs>
              <radialGradient id="jhVel" cx="0.5" cy="0.4" r="0.8">
                <stop offset="0" stopColor="#fdfaf3" />
                <stop offset="1" stopColor="#f3ebdb" />
              </radialGradient>
            </defs>
            {CELLS.map((pts, i) => (
              <polygon key={i} points={polyPoints(pts)} fill="url(#jhVel)" opacity="0.6" />
            ))}
          </svg>

          {/* the six ornaments — each revolves 360° at its own place, kept inside its section */}
          {ITEMS.map(({ id, label, src, x, y, w, h }, i) => (
            <div
              key={id}
              className="jh-cellbox"
              style={{ clipPath: cellClip(CELLS[i]), WebkitClipPath: cellClip(CELLS[i]) }}
            >
              <div
                className="jh-pos"
                style={{
                  left: `${(x / VW) * 100}%`,
                  top: `${(y / VH) * 100}%`,
                  width: `${(w / VW) * 100}%`,
                  height: `${(h / VH) * 100}%`,
                  animationDelay: `${i * 0.15}s`,
                }}
              >
                <img
                  src={src}
                  alt={label}
                  draggable="false"
                  style={{ "--spin": `${SPIN_SECONDS}s`, animationDelay: `${i * STAGGER}s` }}
                />
              </div>
            </div>
          ))}

          <div className="jh-sheen" />
        </div>

        {/* Stationary frame — dividers are clipped to the outline, so nothing pokes outside */}
        <svg className="jh-frame" viewBox={`0 0 ${VW} ${VH}`} aria-hidden="true">
          <defs>
            <clipPath id="jhOuter">
              <polygon points={OUTER} />
            </clipPath>
          </defs>
          <g fill="none" stroke={BORDER_COLOR}>
            <g clipPath="url(#jhOuter)" strokeLinecap="square">
              {DIVIDERS.map(([x1, y1, x2, y2], i) => (
                <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} strokeWidth="8" />
              ))}
            </g>
            <polygon points={OUTER} strokeWidth="9" strokeLinejoin="miter" />
          </g>
        </svg>
      </div>
    </section>
  );
}